// Roster cards + promo strip. cards.html#<id> renders one card, cards.html#strip the promo strip.
// Text is real canon from roster_canon.json (generated by tools/canon_to_roster.py from CANON.md).
import { ROSTER } from "./roster.js";
const canon = await (await fetch("roster_canon.json")).json();
const st = document.getElementById("stage");
const esc = (s) => String(s || "").replace(/[<>&]/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" }[c]));
function card(r) {
  const c = canon[r.name] || {};
  const flag = r.art === "MODEL PENDING" ? `<span class="flag">MODEL PENDING</span>` : r.art.startsWith("WIP") ? `<span class="flag wip">${r.art}</span>` : `<span class="flag ok">${r.art}</span>`;
  st.innerHTML = `<div class="card ${r.unlocked ? "" : "locked"}"><div class="hero"><span class="bigk">${r.kanji}</span>
    <img src="${r.full}" class="${r.model ? "" : "sil"}">${flag}</div><div class="txt">
    <div class="tier">${esc(c.tier)} · ${r.unlocked ? "UNLOCKED" : "LOCKED"}</div>
    <h1>${esc(r.name)}<span class="k">${r.kanji}</span></h1><h2>${esc(r.soul)}</h2><div class="sub">${esc(c.subtitle)}</div>
    <blockquote>“${esc(c.quote)}”</blockquote>
    <dl><dt>BODY</dt><dd>Tekken ${esc(r.body)} — ${esc(c.body)}</dd><dt>ELEMENT</dt><dd>${esc(c.element)}</dd>
    <dt>ORIGIN</dt><dd>${esc(r.origin)}</dd><dt>SIGNATURE</dt><dd>${esc(c.signature)}</dd></dl></div></div>`;
}
function strip() {
  const ids = (new URLSearchParams(location.search).get("ids") || "pantera,zui,demonio,phantom,saku_ra,negativo").split(",");
  st.innerHTML = `<div class="title">EASTERN MIND · WESTERN HEART <span class="k">西部の心</span></div><div class="strip">` +
    ids.map((id) => ROSTER.find((r) => r.id === id)).filter(Boolean).map((r) =>
      `<div class="s"><span class="k">${r.kanji}</span><img src="${r.full}" class="${r.model ? "" : "sil"}"><b>${esc(r.name)}</b></div>`).join("") + `</div>`;
}
function route() { const h = location.hash.slice(1) || "pantera"; h === "strip" ? strip() : card(ROSTER.find((r) => r.id === h) || ROSTER[0]); }
addEventListener("hashchange", route); route();
await Promise.all([...document.images].map((i) => i.decode().catch(() => {})));
window.__WH_CARDS_READY = true;
